(7474492, 1187600, 23484, '<td valign="top">Great job on the processing.</td>', 'Great job on the processing.', '2016-09-18 16:32:28.000000', NULL, 1),
(7474516, 1187522, 114285, '<td valign="top">There''s usually one standout entry in these types of select challenges, and this is the ONE!! Brilliant editing enhances the craftsman''s work. My top pick for sure!</td>', 'There''s usually one standout entry in these types of select challenges, and this is the ONE!! Brilliant editing enhances the craftsman''s work. My top pick for sure!', '2016-09-18 23:00:33.000000', NULL, 1),
