(7474895, 1187497, 101256, '<td valign="top">There''s a lot going on here - fun, work, play - great candid capture.</td>', 'There''s a lot going on here - fun, work, play - great candid capture.', '2016-09-21 09:17:00.000000', NULL, 1),
(7474896, 1187270, 101256, '<td valign="top">This image is slightly out of focus. Image stabilization would have been your friend.</td>', 'This image is slightly out of focus. Image stabilization would have been your friend.', '2016-09-21 09:18:42.000000', NULL, 1),
(7474897, 1187600, 101256, '<td valign="top">What a great capture and post process - wonderful.</td>', 'What a great capture and post process - wonderful.', '2016-09-21 09:19:30.000000', NULL, 1),
