(7474899, 1187643, 101256, '<td valign="top">All hair dressers/barbers have to be good story tellers.  Great candid.</td>', 'All hair dressers/barbers have to be good story tellers.  Great candid.', '2016-09-21 09:20:40.000000', NULL, 1),
